import { chromium } from 'playwright'
const browser = await chromium.launch()
const page = await browser.newPage()
const errs = []
page.on('pageerror', (e) => errs.push(`[pageerror] ${e.message}`))
await page.goto('http://127.0.0.1:8081/#/market-monitor', { waitUntil: 'networkidle', timeout: 40000 }).catch((e)=>errs.push('goto '+e.message))
await page.waitForTimeout(3000)
const info = await page.evaluate(() => {
  const header = document.querySelector('header')
  const img = header ? header.querySelector('img') : null
  const lucide = header ? header.querySelector('svg') : null
  let configSysLogo = null
  try {
    // find Vuex state via app root
    const app = document.querySelector('#app')?.__vue__
    // walk to store
    let store = null
    let cur = app
    while (cur && !store) { store = cur.$store; cur = cur.$parent }
    configSysLogo = store && store.state.app.platformConfig ? store.state.app.platformConfig.sysLogo : 'NO_STORE'
  } catch (e) { configSysLogo = 'ERR ' + e.message }
  return {
    headerHasImg: !!img,
    imgSrc: img ? img.getAttribute('src') : null,
    imgComplete: img ? img.complete : null,
    imgNaturalW: img ? img.naturalWidth : null,
    headerHasLucideSvg: !!lucide,
    configSysLogo
  }
})
console.log(JSON.stringify(info, null, 2))
if (errs.length) console.log('ERRORS', errs.join('\n'))
await browser.close()

